import anthropic
import os
from datetime import datetime
from typing import Dict, List

class EcommerceCustomerServiceAgent:
    def __init__(self, api_key):
        self.client = anthropic.Anthropic(api_key=api_key)
        self.conversation_history = []

        # 知识库（实际应用中从数据库加载）
        self.knowledge_base = {
            &#39;退货政策&#39;: &#39;购买后7天内，商品未使用且包装完好，可申请退货。&#39;,
            &#39;物流查询&#39;: &#39;请提供订单号，我帮您查询物流信息。&#39;,
            &#39;优惠活动&#39;: &#39;当前有满300减50活动，使用优惠码SAVE50。&#39;
        }

        # 订单数据库（模拟）
        self.orders_db = {
            &#39;ORD123456&#39;: {
                &#39;order_id&#39;: &#39;ORD123456&#39;,
                &#39;user_id&#39;: &#39;USER001&#39;,
                &#39;items&#39;: [{&#39;name&#39;: &#39;iPhone 15&#39;, &#39;price&#39;: 5999, &#39;quantity&#39;: 1}],
                &#39;status&#39;: &#39;已发货&#39;,
                &#39;tracking_number&#39;: &#39;SF1234567890&#39;,
                &#39;order_date&#39;: &#39;2024-01-10&#39;,
                &#39;estimated_delivery&#39;: &#39;2024-01-16&#39;
            }
        }

    def classify_intent(self, user_message: str) -&gt; Dict:
        &#34;&#34;&#34;识别用户意图&#34;&#34;&#34;

        intent_prompt = f&#34;&#34;&#34;
        分析以下客户消息的意图，输出JSON格式：

        客户消息：{user_message}

        意图类别：
        - order_inquiry（订单查询）
        - return_request（退货申请）
        - product_question（商品咨询）
        - complaint（投诉）
        - logistics_tracking（物流查询）
        - other（其他）

        输出格式：
        {{
            &#34;intent&#34;: &#34;意图类别&#34;,
            &#34;confidence&#34;: 0.95,
            &#34;entities&#34;: {{
                &#34;order_id&#34;: &#34;订单号（如果提到）&#34;,
                &#34;product_name&#34;: &#34;商品名称（如果提到）&#34;
            }},
            &#34;urgency&#34;: &#34;低/中/高&#34;,
            &#34;needs_human&#34;: false
        }}
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=500,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: intent_prompt}
            ]
        )

        import json
        return json.loads(message.content[0].text)

    def query_order(self, order_id: str) -&gt; Dict:
        &#34;&#34;&#34;查询订单信息&#34;&#34;&#34;
        return self.orders_db.get(order_id, None)

    def handle_order_inquiry(self, order_id: str) -&gt; str:
        &#34;&#34;&#34;处理订单查询&#34;&#34;&#34;
        order = self.query_order(order_id)

        if not order:
            return &#34;抱歉，未找到该订单信息，请确认订单号是否正确。&#34;

        response = f&#34;&#34;&#34;
        您的订单信息如下：

          订单号：{order[&#39;order_id&#39;]}
          下单时间：{order[&#39;order_date&#39;]}
          当前状态：{order[&#39;status&#39;]}
          物流单号：{order[&#39;tracking_number&#39;]}
        ⏰ 预计送达：{order[&#39;estimated_delivery&#39;]}

        商品清单：
        &#34;&#34;&#34;

        for item in order[&#39;items&#39;]:
            response += f&#34;\n- {item[&#39;name&#39;]} × {item[&#39;quantity&#39;]} (¥{item[&#39;price&#39;]})&#34;

        return response

    def handle_return_request(self, order_id: str) -&gt; str:
        &#34;&#34;&#34;处理退货申请&#34;&#34;&#34;
        order = self.query_order(order_id)

        if not order:
            return &#34;抱歉，未找到该订单信息。&#34;

        # 检查退货资格
        from datetime import datetime, timedelta
        order_date = datetime.strptime(order[&#39;order_date&#39;], &#39;%Y-%m-%d&#39;)
        days_passed = (datetime.now() - order_date).days

        if days_passed &gt; 7:
            return f&#34;抱歉，该订单已超过7天退货期限（已过{days_passed}天）。如有特殊情况，请联系人工客服。&#34;

        return f&#34;&#34;&#34;
        ✅ 您的订单符合退货条件。

        请按以下步骤操作：
        1. 确保商品未使用，包装完好
        2. 在【我的订单】中选择该订单，点击【申请退货】
        3. 填写退货原因并上传商品照片
        4. 等待审核（1个工作日内）
        5. 审核通过后，将商品寄回（运费由我们承担）

        退货地址将在审核通过后发送给您。

        需要我现在帮您提交退货申请吗？
        &#34;&#34;&#34;

    def generate_response(self, user_message: str, intent_info: Dict) -&gt; str:
        &#34;&#34;&#34;根据意图生成响应&#34;&#34;&#34;

        intent = intent_info[&#39;intent&#39;]
        entities = intent_info[&#39;entities&#39;]

        if intent == &#39;order_inquiry&#39; and entities.get(&#39;order_id&#39;):
            return self.handle_order_inquiry(entities[&#39;order_id&#39;])

        elif intent == &#39;return_request&#39; and entities.get(&#39;order_id&#39;):
            return self.handle_return_request(entities[&#39;order_id&#39;])

        elif intent == &#39;logistics_tracking&#39;:
            if entities.get(&#39;order_id&#39;):
                order = self.query_order(entities[&#39;order_id&#39;])
                if order:
                    return f&#34;您的订单物流单号是：{order[&#39;tracking_number&#39;]}，当前状态：{order[&#39;status&#39;]}，预计{order[&#39;estimated_delivery&#39;]}送达。&#34;

        else:
            # 使用LLM生成通用回复
            context = &#34;\n&#34;.join([f&#34;{msg[&#39;role&#39;]}: {msg[&#39;content&#39;]}&#34; for msg in self.conversation_history[-3:]])

            response_prompt = f&#34;&#34;&#34;
            你是一个专业的电商客服，请根据以下对话历史和知识库回答客户问题：

            知识库：
            {self.knowledge_base}

            对话历史：
            {context}

            客户最新消息：{user_message}

            要求：
            1. 专业、礼貌、热情
            2. 回答简洁明了
            3. 如果不确定，建议联系人工客服
            4. 适当使用emoji增加亲和力
            &#34;&#34;&#34;

            message = self.client.messages.create(
                model=&#34;claude-sonnet-4-5-20250929&#34;,
                max_tokens=800,
                messages=[
                    {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: response_prompt}
                ]
            )

            return message.content[0].text

    def chat(self, user_message: str) -&gt; str:
        &#34;&#34;&#34;主对话接口&#34;&#34;&#34;
        print(f&#34;  客户: {user_message}&#34;)

        # 1. 识别意图
        intent_info = self.classify_intent(user_message)
        print(f&#34;  意图识别: {intent_info[&#39;intent&#39;]} (置信度: {intent_info[&#39;confidence&#39;]})&#34;)

        # 2. 判断是否需要转人工
        if intent_info.get(&#39;needs_human&#39;) or intent_info[&#39;urgency&#39;] == &#39;高&#39;:
            response = &#34;您的问题比较复杂，我帮您转接人工客服，请稍候...&#34;
            # 实际应用中调用人工客服系统
        else:
            # 3. 生成响应
            response = self.generate_response(user_message, intent_info)

        # 4. 更新对话历史
        self.conversation_history.append({
            &#39;role&#39;: &#39;user&#39;,
            &#39;content&#39;: user_message,
            &#39;timestamp&#39;: datetime.now().isoformat()
        })
        self.conversation_history.append({
            &#39;role&#39;: &#39;assistant&#39;,
            &#39;content&#39;: response,
            &#39;timestamp&#39;: datetime.now().isoformat()
        })

        print(f&#34;  客服: {response}\n&#34;)
        return response

