import anthropic
import os
from datetime import datetime
from typing import List, Dict

class ContentCreationAgent:
    def __init__(self, api_key):
        self.client = anthropic.Anthropic(api_key=api_key)

        # 平台规则（实际应用中更复杂）
        self.platform_rules = {
            &#39;知乎&#39;: {
                &#39;min_length&#39;: 1000,
                &#39;max_length&#39;: 8000,
                &#39;style&#39;: &#39;专业深度&#39;,
                &#39;structure&#39;: &#39;TL;DR + 正文 + 总结&#39;
            },
            &#39;公众号&#39;: {
                &#39;min_length&#39;: 1500,
                &#39;max_length&#39;: 5000,
                &#39;style&#39;: &#39;通俗易懂&#39;,
                &#39;structure&#39;: &#39;引入 + 正文 + 引导关注&#39;
            },
            &#39;小红书&#39;: {
                &#39;min_length&#39;: 300,
                &#39;max_length&#39;: 1000,
                &#39;style&#39;: &#39;轻松活泼&#39;,
                &#39;structure&#39;: &#39;标题党 + 图文并茂 + 话题标签&#39;
            }
        }

    def monitor_hot_topics(self) -&gt; List[Dict]:
        &#34;&#34;&#34;
        监控热点话题（实际应用中集成数据源API）
        这里模拟返回热点数据
        &#34;&#34;&#34;
        # 实际应用中调用微博热搜、知乎热榜、百度指数等API
        return [
            {
                &#39;keyword&#39;: &#39;AI Agent应用&#39;,
                &#39;heat_index&#39;: 8500,
                &#39;trend&#39;: &#39;上升&#39;,
                &#39;related_keywords&#39;: [&#39;智能客服&#39;, &#39;办公自动化&#39;, &#39;Claude&#39;],
                &#39;competition&#39;: &#39;中&#39;
            },
            {
                &#39;keyword&#39;: &#39;RAG技术&#39;,
                &#39;heat_index&#39;: 6200,
                &#39;trend&#39;: &#39;稳定&#39;,
                &#39;related_keywords&#39;: [&#39;向量数据库&#39;, &#39;检索增强&#39;, &#39;LangChain&#39;],
                &#39;competition&#39;: &#39;高&#39;
            }
        ]

    def generate_topic_ideas(self, keyword: str, target_audience: str) -&gt; List[Dict]:
        &#34;&#34;&#34;生成选题方案&#34;&#34;&#34;

        topics_prompt = f&#34;&#34;&#34;
        基于关键词&#34;{keyword}&#34;，为{target_audience}生成5个内容选题。

        每个选题包含：
        1. 标题（吸引人且准确）
        2. 角度（独特视角）
        3. 受众痛点（解决什么问题）
        4. 内容大纲（3-5个要点）
        5. 预估热度（1-10分）

        输出JSON格式：
        {{
            &#34;topic_ideas&#34;: [
                {{
                    &#34;title&#34;: &#34;标题&#34;,
                    &#34;angle&#34;: &#34;角度&#34;,
                    &#34;pain_points&#34;: [&#34;痛点1&#34;, &#34;痛点2&#34;],
                    &#34;outline&#34;: [&#34;要点1&#34;, &#34;要点2&#34;, &#34;要点3&#34;],
                    &#34;estimated_heat&#34;: 8
                }}
            ]
        }}
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=2000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: topics_prompt}
            ]
        )

        import json
        return json.loads(message.content[0].text)[&#39;topic_ideas&#39;]

    def create_content(self, topic: Dict, platform: str, target_length: int) -&gt; str:
        &#34;&#34;&#34;根据选题生成内容&#34;&#34;&#34;

        platform_rules = self.platform_rules.get(platform, {})

        content_prompt = f&#34;&#34;&#34;
        请为{platform}平台创作一篇文章：

        选题信息：
        - 标题：{topic[&#39;title&#39;]}
        - 角度：{topic[&#39;angle&#39;]}
        - 解决痛点：{&#39;, &#39;.join(topic[&#39;pain_points&#39;])}
        - 内容大纲：{&#39;, &#39;.join(topic[&#39;outline&#39;])}

        平台要求：
        - 字数：{target_length}字左右
        - 风格：{platform_rules.get(&#39;style&#39;, &#39;专业&#39;)}
        - 结构：{platform_rules.get(&#39;structure&#39;, &#39;标准&#39;)}

        内容要求：
        1. 开篇吸引人，快速切入主题
        2. 论据充分，有数据和案例支撑
        3. 结构清晰，使用小标题分段
        4. 语言流畅，通俗易懂
        5. 结尾有行动号召
        6. 适当使用emoji增加可读性（但不过度）

        请直接输出文章正文。
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=4000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: content_prompt}
            ]
        )

        return message.content[0].text

    def optimize_title(self, original_title: str, platform: str) -&gt; List[str]:
        &#34;&#34;&#34;标题优化，生成多个备选&#34;&#34;&#34;

        title_prompt = f&#34;&#34;&#34;
        为以下标题生成5个优化版本，适合{platform}平台：

        原标题：{original_title}

        优化方向：
        1. 数字化（加入数字增加可信度）
        2. 痛点化（直击用户痛点）
        3. 好奇化（激发好奇心）
        4. 实用化（强调实用价值）
        5. 热点化（结合热点话题）

        每个标题长度控制在20-30字。

        输出JSON格式：
        {{
            &#34;optimized_titles&#34;: [
                {{&#34;title&#34;: &#34;标题&#34;, &#34;type&#34;: &#34;类型&#34;, &#34;reason&#34;: &#34;优化理由&#34;}}
            ]
        }}
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=1000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: title_prompt}
            ]
        )

        import json
        return json.loads(message.content[0].text)[&#39;optimized_titles&#39;]

    def adapt_to_platform(self, content: str, from_platform: str, to_platform: str) -&gt; str:
        &#34;&#34;&#34;跨平台内容改写&#34;&#34;&#34;

        adapt_prompt = f&#34;&#34;&#34;
        请将以下内容从{from_platform}平台改写为适合{to_platform}平台的版本：

        原内容：
        {content}

        改写要求：
        - 长度调整为{self.platform_rules[to_platform][&#39;min_length&#39;]}-{self.platform_rules[to_platform][&#39;max_length&#39;]}字
        - 风格调整为{self.platform_rules[to_platform][&#39;style&#39;]}
        - 结构调整为{self.platform_rules[to_platform][&#39;structure&#39;]}
        - 保留核心观点和关键信息
        - 适配平台用户阅读习惯

        请直接输出改写后的内容。
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=4000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: adapt_prompt}
            ]
        )

        return message.content[0].text

    def run_full_workflow(self, keyword: str, target_audience: str, platforms: List[str]):
        &#34;&#34;&#34;完整内容创作工作流&#34;&#34;&#34;
        print(f&#34;  正在监控热点话题...&#34;)
        hot_topics = self.monitor_hot_topics()
        print(f&#34;发现 {len(hot_topics)} 个热点&#34;)

        print(f&#34;\n  正在生成选题...&#34;)
        topic_ideas = self.generate_topic_ideas(keyword, target_audience)
        print(f&#34;生成 {len(topic_ideas)} 个选题方案&#34;)

        # 选择热度最高的选题
        best_topic = max(topic_ideas, key=lambda x: x[&#39;estimated_heat&#39;])
        print(f&#34;\n✅ 选定选题：{best_topic[&#39;title&#39;]}&#34;)

        print(f&#34;\n  正在创作内容...&#34;)
        # 首先为主平台创作
        primary_platform = platforms[0]
        original_content = self.create_content(
            best_topic,
            primary_platform,
            self.platform_rules[primary_platform][&#39;max_length&#39;]
        )

        print(f&#34;\n  正在优化标题...&#34;)
        optimized_titles = self.optimize_title(best_topic[&#39;title&#39;], primary_platform)

        print(f&#34;\n  正在适配其他平台...&#34;)
        adapted_contents = {}
        for platform in platforms[1:]:
            adapted_contents[platform] = self.adapt_to_platform(
                original_content,
                primary_platform,
                platform
            )

        return {
            &#39;topic&#39;: best_topic,
            &#39;original_content&#39;: original_content,
            &#39;optimized_titles&#39;: optimized_titles,
            &#39;adapted_contents&#39;: adapted_contents
        }

# 使用示例
