import anthropic
import os
import pandas as pd
import json
from typing import Dict, List

class DataAnalysisAgent:
    def __init__(self, api_key):
        self.client = anthropic.Anthropic(api_key=api_key)

    def load_data(self, file_path: str) -&gt; pd.DataFrame:
        &#34;&#34;&#34;加载数据&#34;&#34;&#34;
        # 支持多种格式
        if file_path.endswith(&#39;.csv&#39;):
            return pd.read_csv(file_path)
        elif file_path.endswith(&#39;.xlsx&#39;):
            return pd.read_excel(file_path)
        elif file_path.endswith(&#39;.json&#39;):
            return pd.read_json(file_path)
        else:
            raise ValueError(&#34;不支持的文件格式&#34;)

    def understand_data(self, df: pd.DataFrame) -&gt; Dict:
        &#34;&#34;&#34;理解数据结构和内容&#34;&#34;&#34;

        # 生成数据摘要
        data_summary = {
            &#39;shape&#39;: df.shape,
            &#39;columns&#39;: df.columns.tolist(),
            &#39;dtypes&#39;: df.dtypes.to_dict(),
            &#39;missing_values&#39;: df.isnull().sum().to_dict(),
            &#39;sample_data&#39;: df.head(5).to_dict(),
            &#39;statistics&#39;: df.describe().to_dict()
        }

        # 使用LLM理解数据含义
        understanding_prompt = f&#34;&#34;&#34;
        分析以下数据集的结构和内容，给出数据理解报告：

        数据摘要：
        {json.dumps(data_summary, ensure_ascii=False, indent=2, default=str)}

        请分析：
        1. 这是什么类型的数据（业务领域）
        2. 每个字段的业务含义
        3. 数据质量评估（缺失值、异常值）
        4. 可能的分析方向
        5. 需要注意的问题

        输出JSON格式。
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=2000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: understanding_prompt}
            ]
        )

        return json.loads(message.content[0].text)

    def generate_analysis_plan(self, data_understanding: Dict, business_question: str) -&gt; List[Dict]:
        &#34;&#34;&#34;生成分析计划&#34;&#34;&#34;

        plan_prompt = f&#34;&#34;&#34;
        基于数据理解和业务问题，制定数据分析计划：

        数据理解：
        {json.dumps(data_understanding, ensure_ascii=False, indent=2)}

        业务问题：{business_question}

        请制定分析计划，包含：
        1. 分析步骤（顺序执行）
        2. 每步的分析方法
        3. 需要的可视化
        4. 预期产出

        输出JSON格式：
        {{
            &#34;analysis_steps&#34;: [
                {{
                    &#34;step&#34;: 1,
                    &#34;name&#34;: &#34;步骤名称&#34;,
                    &#34;method&#34;: &#34;分析方法&#34;,
                    &#34;visualization&#34;: &#34;可视化类型&#34;,
                    &#34;expected_output&#34;: &#34;预期产出&#34;
                }}
            ]
        }}
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=2000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: plan_prompt}
            ]
        )

        return json.loads(message.content[0].text)[&#39;analysis_steps&#39;]

    def generate_code(self, step: Dict, df_info: Dict) -&gt; str:
        &#34;&#34;&#34;生成分析代码&#34;&#34;&#34;

        code_prompt = f&#34;&#34;&#34;
        根据分析步骤生成Python代码（使用pandas、numpy、matplotlib）：

        分析步骤：
        {json.dumps(step, ensure_ascii=False, indent=2)}

        数据框信息：
        {json.dumps(df_info, ensure_ascii=False, indent=2)}

        代码要求：
        1. 使用df作为数据框变量名
        2. 添加必要的注释
        3. 处理可能的异常
        4. 将结果保存到变量result中
        5. 如果有可视化，保存到文件

        只输出Python代码，不要其他解释。
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=1500,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: code_prompt}
            ]
        )

        code = message.content[0].text
        # 清理代码块标记
        if code.startswith(&#39;```python&#39;):
            code = code[9:]
        if code.endswith(&#39;```&#39;):
            code = code[:-3]

        return code.strip()

    def execute_analysis(self, df: pd.DataFrame, code: str) -&gt; Dict:
        &#34;&#34;&#34;执行分析代码&#34;&#34;&#34;
        try:
            # 准备执行环境
            exec_globals = {
                &#39;df&#39;: df,
                &#39;pd&#39;: pd,
                &#39;np&#39;: __import__(&#39;numpy&#39;),
                &#39;plt&#39;: __import__(&#39;matplotlib.pyplot&#39;),
                &#39;result&#39;: None
            }

            # 执行代码
            exec(code, exec_globals)

            return {
                &#39;success&#39;: True,
                &#39;result&#39;: exec_globals[&#39;result&#39;],
                &#39;error&#39;: None
            }
        except Exception as e:
            return {
                &#39;success&#39;: False,
                &#39;result&#39;: None,
                &#39;error&#39;: str(e)
            }

    def generate_insights(self, analysis_results: List[Dict], business_question: str) -&gt; str:
        &#34;&#34;&#34;从分析结果中提取洞察&#34;&#34;&#34;

        insights_prompt = f&#34;&#34;&#34;
        基于以下分析结果，回答业务问题并给出洞察：

        业务问题：{business_question}

        分析结果：
        {json.dumps(analysis_results, ensure_ascii=False, indent=2, default=str)}

        请生成分析报告，包含：
        1. 核心发现（3-5条）
        2. 数据证据支持
        3. 业务建议
        4. 风险提示
        5. 下一步行动建议

        报告要专业、数据驱动、可执行。
        &#34;&#34;&#34;

        message = self.client.messages.create(
            model=&#34;claude-sonnet-4-5-20250929&#34;,
            max_tokens=3000,
            messages=[
                {&#34;role&#34;: &#34;user&#34;, &#34;content&#34;: insights_prompt}
            ]
        )

        return message.content[0].text

    def run(self, data_path: str, business_question: str):
        &#34;&#34;&#34;完整分析流程&#34;&#34;&#34;
        print(&#34;  正在加载数据...&#34;)
        df = self.load_data(data_path)
        print(f&#34;数据规模：{df.shape[0]}行 × {df.shape[1]}列&#34;)

        print(&#34;\n  正在理解数据...&#34;)
        data_understanding = self.understand_data(df)
        print(f&#34;数据类型：{data_understanding.get(&#39;data_type&#39;, &#39;未知&#39;)}&#34;)

        print(&#34;\n  正在制定分析计划...&#34;)
        analysis_plan = self.generate_analysis_plan(data_understanding, business_question)
        print(f&#34;分析步骤：{len(analysis_plan)}步&#34;)

        print(&#34;\n⚙️ 正在执行分析...&#34;)
        analysis_results = []

        for step in analysis_plan:
            print(f&#34;\n  步骤 {step[&#39;step&#39;]}: {step[&#39;name&#39;]}&#34;)

            # 生成代码
            code = self.generate_code(step, {
                &#39;columns&#39;: df.columns.tolist(),
                &#39;dtypes&#39;: df.dtypes.to_dict()
            })

            # 执行分析
            result = self.execute_analysis(df, code)

            analysis_results.append({
                &#39;step&#39;: step,
                &#39;code&#39;: code,
                &#39;result&#39;: result
            })

            if result[&#39;success&#39;]:
                print(f&#34;  ✅ 完成&#34;)
            else:
                print(f&#34;  ❌ 失败: {result[&#39;error&#39;]}&#34;)

        print(&#34;\n  正在生成洞察...&#34;)
        insights = self.generate_insights(analysis_results, business_question)

        return {
            &#39;data_understanding&#39;: data_understanding,
            &#39;analysis_plan&#39;: analysis_plan,
            &#39;analysis_results&#39;: analysis_results,
            &#39;insights&#39;: insights
        }

