def calculate_agent_roi(
    task_frequency: int,  # 每月任务量
    time_per_task_manual: float,  # 人工处理单个任务时间（小时）
    time_per_task_agent: float,  # Agent处理单个任务时间（小时）
    hourly_cost: float,  # 人工小时成本（元）
    agent_monthly_cost: float,  # Agent月度成本（元）
    error_rate_manual: float,  # 人工错误率
    error_rate_agent: float,  # Agent错误率
    error_cost: float  # 单个错误成本（元）
) -&gt; dict:
    &#34;&#34;&#34;
    计算使用AI Agent的ROI
    &#34;&#34;&#34;

    # 人工成本
    manual_time_cost = task_frequency * time_per_task_manual * hourly_cost
    manual_error_cost = task_frequency * error_rate_manual * error_cost
    total_manual_cost = manual_time_cost + manual_error_cost

    # Agent成本
    agent_time_cost = task_frequency * time_per_task_agent * hourly_cost  # 仍需人工监督
    agent_error_cost = task_frequency * error_rate_agent * error_cost
    total_agent_cost = agent_monthly_cost + agent_time_cost + agent_error_cost

    # ROI计算
    monthly_savings = total_manual_cost - total_agent_cost
    roi_percentage = (monthly_savings / total_agent_cost) * 100 if total_agent_cost &gt; 0 else 0
    payback_period = agent_monthly_cost / monthly_savings if monthly_savings &gt; 0 else float(&#39;inf&#39;)

    return {
        &#39;manual_cost&#39;: {
            &#39;time_cost&#39;: manual_time_cost,
            &#39;error_cost&#39;: manual_error_cost,
            &#39;total&#39;: total_manual_cost
        },
        &#39;agent_cost&#39;: {
            &#39;platform_cost&#39;: agent_monthly_cost,
            &#39;time_cost&#39;: agent_time_cost,
            &#39;error_cost&#39;: agent_error_cost,
            &#39;total&#39;: total_agent_cost
        },
        &#39;savings&#39;: {
